for (const order of orders) {
  await sender.sendMessages({
    body: JSON.stringify(order),
    contentType: "application/json",
    sessionId: order.id  // Groups all steps for this order
  });
}

import { ServiceBusClient } from "@azure/service-bus";

const client = new ServiceBusClient(connectionString);
const processor = client.createSessionProcessor("orders", {
  maxConcurrentSessions: 5,
  autoCompleteMessages: false
});

processor.subscribe({
  async processMessage(message) {
    const order = JSON.parse(message.body);
    console.log(`Processing order ${message.sessionId} step ${order.step}`);
    await processor.completeMessage(message);
  }
});
